```csharp
using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel.Connectors.Qdrant;
using Moq;
using Xunit;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class QdrantServiceCollectionExtensionsTests
    {
        [Fact]
        public void GetCollectionOptions_ShouldReturnOptionsWithEmbeddingGenerator()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockEmbeddingGenerator = new Mock<IEmbeddingGenerator>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IEmbeddingGenerator))).Returns(mockEmbeddingGenerator.Object);

            var optionsProvider = new Func<IServiceProvider, QdrantCollectionOptions?>(sp => null);

            // Act
            var result = QdrantServiceCollectionExtensions.GetCollectionOptions(mockServiceProvider.Object, optionsProvider);

            // Assert
            Assert.NotNull(result);
            Assert.Same(mockEmbeddingGenerator.Object, result.EmbeddingGenerator);
        }

        [Fact]
        public void GetCollectionOptions_ShouldReturnExistingOptionsIfEmbeddingGeneratorIsProvided()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockEmbeddingGenerator = new Mock<IEmbeddingGenerator>();
            var existingOptions = new QdrantCollectionOptions { EmbeddingGenerator = mockEmbeddingGenerator.Object };

            var optionsProvider = new Func<IServiceProvider, QdrantCollectionOptions?>(sp => existingOptions);

            // Act
            var result = QdrantServiceCollectionExtensions.GetCollectionOptions(mockServiceProvider.Object, optionsProvider);

            // Assert
            Assert.NotNull(result);
            Assert.Same(existingOptions, result);
        }
    }
}
```

